function specialtyIcon(id){const mark=SPECIALTY_MARKS[id]||SPECIALTY_MARKS.sp;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('class','skill-pictogram specialty-pictogram');svg.setAttribute('aria-hidden','true');svg.dataset.specialty=id;svg.innerHTML='<g fill="none" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">'+mark.shape+'</g>';return svg}
function skillIdentityIcon(id){if(RIDER_SKILL_MARKS[id])return riderSkillIcon(id);return SPECIALTY_MARKS[id]?specialtyIcon(id):skillIcon(topicForSkill(id).id)}
